type Column struct {
    Name string `json:"name"`
    Type string `json:"type"`
}

type Table struct {
    Schema struct {
        Columns []Column `json:"columns"`
    } `json:"schema"`
    Rows [][]interface{} `json:"rows"`
}

func normalizeJSON(data interface{}) Table {
    table := Table{}
    switch val := data.(type) {
    case []interface{}:
        for _, elem := range val {
            row := make([]interface{}, len(table.Schema.Columns))
            switch v := elem.(type) {
            case map[string]interface{}:
                for key, value := range v {
                    found := false
                    it := 0
                    for _, col := range table.Schema.Columns {
                        if col.Name == key {
                            found = true
                            break
                        }
                        it++
                    }
                    if !found {
                        table.Schema.Columns = append(table.Schema.Columns, Column{Name: key, Type: inferType(value)})
                    }
                    if len(row) < len(table.Schema.Columns) {
                        row = append(row, make([]interface{}, len(table.Schema.Columns)-len(row))...)
                    }
                    switch value.(type) {
                    case map[string]interface{}, []interface{}:
                        row[it] = normalizeJSON(value)
                    default:
                        row[it] = value
                    }
                }
            default:
                if len(table.Schema.Columns) == 0 {
                    table.Schema.Columns = append(table.Schema.Columns, Column{Name: "value", Type: inferType(v)})
                }
                row = append(row, v)
            }
            table.Rows = append(table.Rows, row)
        }
    case map[string]interface{}:
        row := []interface{}{}
        for key, value := range val {
            table.Schema.Columns = append(table.Schema.Columns, Column{Name: key, Type: inferType(value)})
            switch value.(type) {
            case map[string]interface{}, []interface{}:
                row = append(row, normalizeJSON(value))
            default:
                row = append(row, value)
            }
        }
        table.Rows = append(table.Rows, row)
    default:
        table.Schema.Columns = append(table.Schema.Columns, Column{Name: "value", Type: inferType(val)})
        table.Rows = append(table.Rows, []interface{}{val})
    }
    return table
}

func parseNDJSON(data []byte) (Table, error) {
    parsed := Table{}
    scanner := bufio.NewScanner(bytes.NewReader(data))
    for scanner.Scan() {
        line := scanner.Bytes()
        var obj interface{}
        if err := json.Unmarshal(line, &obj); err != nil {
            return Table{}, fmt.Errorf("failed to parse NDJSON line: %v", err)
        }
        switch v := obj.(type) {
        case map[string]interface{}:
            row := make([]interface{}, len(parsed.Schema.Columns))
            for key, value := range v {
                found := false
                it := 0
                for _, col := range parsed.Schema.Columns {
                    if col.Name == key {
                        found = true
                        break
                    }
                    it++
                }
                if !found {
                    parsed.Schema.Columns = append(parsed.Schema.Columns, Column{Name: key, Type: inferType(value)})
                }
                if len(row) < len(parsed.Schema.Columns) {
                    row = append(row, make([]interface{}, len(parsed.Schema.Columns)-len(row))...)
                }
                switch v := value.(type) {
                case map[string]interface{}:
                    row[it] = "normalizeJSON(value)" // Placeholder, should call normalizeJSON
                default:
                    row[it] = v
                }
            }
            parsed.Rows = append(parsed.Rows, row)
        default:
            return Table{}, fmt.Errorf("expected JSON object in NDJSON, got %T", v)
        }
    }
    if err := scanner.Err(); err != nil {
        return Table{}, fmt.Errorf("error reading NDJSON data: %v", err)
    }
    return parsed, nil
}

func detectJSONType(data []byte) string {
    data = bytes.TrimSpace(data)
    if len(data) == 0 {
        return "unknown"
    }
    if data[0] == '[' {
        return "array"
    } else if data[0] == '{' {
        if bytes.Contains(data, []byte("}\n{")) {
            return "ndjson"
        }
        return "object"
    }
    return "unknown"
}

